@import url('https://fonts.googleapis.com/css2?family=Saira+Condensed:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Reebok DNA — vector red and blue on stark white, condensed italic speed, zero radius */
.theme-reebok-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.970 0 0);
  --surface-2: oklch(0.907 0 0);
  --fg: oklch(0.000 0 0);
  --fg-muted: oklch(0.556 0 0);
  --accent: oklch(0.586 0.228 28.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.413 0.140 264.8);
  --line: oklch(0.196 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.55 0.2 27);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;
  --shadow-1: none;
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 2px;
  --blur-amount: 0px;
  --font-display: "Saira Condensed", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-reebok-dna h1,
.theme-reebok-dna h2,
.theme-reebok-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-reebok-dna { --font-ui: var(--font-display); }
.theme-reebok-dna h1, .theme-reebok-dna h2 { text-transform: uppercase; font-style: italic; }
.theme-reebok-dna h2::before { content: "/"; color: var(--accent); margin-right: 0.3em; font-weight: 700; }
.theme-reebok-dna button { text-transform: uppercase; font-style: italic; letter-spacing: 0.06em; }

/* depth */
.theme-reebok-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-reebok-dna thead th { font-family: var(--font-display); font-style: italic; text-transform: uppercase; letter-spacing: 0.08em; border-bottom: 3px solid var(--fg); background: transparent; }
.theme-reebok-dna td { border-bottom: 1px solid oklch(0 0 0 / 12%); }
.theme-reebok-dna tbody tr:hover { background: var(--surface); box-shadow: inset 4px 0 0 var(--accent); }
.theme-reebok-dna a { color: var(--accent-2); font-weight: 600; text-decoration: none; border-bottom: 2px solid var(--accent); }
.theme-reebok-dna a:hover { color: var(--accent); border-bottom-color: var(--accent-2); }
.theme-reebok-dna input, .theme-reebok-dna select, .theme-reebok-dna textarea { border: var(--border-width) solid var(--fg); border-radius: 0; background: var(--bg); }
.theme-reebok-dna input:focus-visible, .theme-reebok-dna select:focus-visible, .theme-reebok-dna textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 4px 4px 0 color-mix(in oklab, var(--accent) 30%, transparent); }
.theme-reebok-dna kbd { font-family: var(--font-display); font-style: italic; border: 2px solid var(--fg); border-radius: 0; padding: 0.05em 0.5em; background: var(--bg); }
.theme-reebok-dna .label-caps { font-style: italic; }
.theme-reebok-dna .label-caps::before { content: "//"; color: var(--accent); margin-right: 0.4em; font-weight: 700; }
.theme-reebok-dna .themed-border { border: 2px solid var(--fg); border-left: 6px solid var(--accent); }
.theme-reebok-dna button { transition: transform 90ms ease, box-shadow 90ms ease; }
.theme-reebok-dna button:hover { box-shadow: 4px 4px 0 var(--accent-2); transform: translate(-2px, -2px); }
.theme-reebok-dna button:active { box-shadow: none; transform: translate(0, 0); }
.theme-reebok-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-reebok-dna ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-reebok-dna ::-webkit-scrollbar-thumb { background: var(--accent); border-radius: 0; }
.theme-reebok-dna ::-webkit-scrollbar-thumb:hover { background: var(--accent-2); }

/* alt mode: night track — vector red and sky blue on carbon black */
.theme-reebok-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.640 0.225 28.3);
  --accent-2: oklch(0.700 0.130 250.0);
}
.theme-reebok-dna.alt-mode thead th { border-bottom-color: var(--fg); }
.theme-reebok-dna.alt-mode td { border-bottom-color: oklch(1 0 0 / 14%); }
.theme-reebok-dna.alt-mode input, .theme-reebok-dna.alt-mode select, .theme-reebok-dna.alt-mode textarea { border-color: var(--fg); background: var(--surface); }
.theme-reebok-dna.alt-mode kbd { border-color: var(--fg); background: var(--surface); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
